inline float3 CorrectSpecularLightDirection(float3 lightDirectionWS, float3 viewDirectionWS,
                                            float3 correctionNormalWS, out float correctionAmount)
{
    correctionAmount = 0.0;
    float correctionStrength = saturate(_SpecularViewNormalCorrection);
    if (correctionStrength <= 0.0001h)
        return lightDirectionWS;

    float frontFacing = saturate(dot(correctionNormalWS, viewDirectionWS));
    float maxCorrectionRadians = _SpecularCorrectionMaxAngle * (PI / 180.0h)
        * correctionStrength * frontFacing;
    float3 idealSpecularDirection = SafeNormalize(reflect(-viewDirectionWS, correctionNormalWS));
    float3 correctedDirection = RotateSpecularDirectionTowards(
        lightDirectionWS, idealSpecularDirection, maxCorrectionRadians, correctionAmount);

    // 修正后再次约束俯仰角，避免视角修正突破材质设置的灯光上限。
    return ClampSpecularLightElevation(correctedDirection, viewDirectionWS);
}

inline float3 CompressCorrectedSpecularPeak(float3 specularTerm, float correctionAmount)
{
    if (correctionAmount <= 0.0001)
        return specularTerm;

    float peak = Max3(specularTerm.r, specularTerm.g, specularTerm.b);
    float peakLimit = max(_SpecularCorrectionPeakLimit, 0.001h);
    float kneeStart = peakLimit * 0.5;
    if (peak <= kneeStart)
        return specularTerm;

    float excess = peak - kneeStart;
    float compressedPeak = kneeStart + excess / (1.0 + excess / max(peakLimit - kneeStart, 0.001));
    float compressedScale = compressedPeak / max(peak, 1e-5);
    return specularTerm * lerp(1.0, compressedScale, saturate(correctionAmount));
}

half LinearStep(half minValue, half maxValue, half In) // shadowThreshold - shadowSmooth, shadowThreshold + shadowSmooth, radiance
{
    return saturate((In-minValue) / (maxValue - minValue));
}

