inline void InitializeInputDotData(half3 normalWS, float3 viewDirectionWS, Light_Character mainLight, AdditionalLightData addLightData, out InputDotData inputDotData)
{
    inputDotData = (InputDotData)0;

    //自定义阴影方向
    half3 diffuseDir = addLightData.diffuseDir.xyz;

    half3 cameraViewWS = normalize(TransformViewToWorldDir(half3(0.0h, 0.0h, 1.0h)));
    float CdotL = dot(cameraViewWS.xz, diffuseDir.xz);
    CdotL = acos(CdotL) * 57.29578f;
    CdotL = -max(CdotL - 90.0f, 0.0h);

    //diffuseDir = normalize(RotateAround(diffuseDir, CdotL));
    diffuseDir = addLightData.diffuseDir.xyz;

    inputDotData.NdotL = dot(normalWS, diffuseDir);
    inputDotData.NdotLClamp = saturate(inputDotData.NdotL);
    inputDotData.HalfLambert = inputDotData.NdotL * 0.5h + 0.5h;

    //自定义高光方向
    half3 specularDir = addLightData.specularDir;

    float3 halfDir = SafeNormalize(specularDir + viewDirectionWS);
    inputDotData.HalfDir = halfDir;
    inputDotData.LdotH = saturate(dot(specularDir, halfDir.xyz));
    inputDotData.NdotH = saturate(dot(normalWS.xyz, halfDir.xyz));

    //菲涅尔
    inputDotData.NdotV = dot(normalWS.xyz, viewDirectionWS.xyz);
    inputDotData.NdotVClamp = saturate(inputDotData.NdotV);

    //投影
    #if defined(_RECEIVE_SHADOWS_OFF)
    inputDotData.atten = 1;
    #else
    inputDotData.atten =  LerpWhiteTo(mainLight.shadowAttenuation, addLightData.sceneShadowStrength);
    inputDotData.atten *= mainLight.distanceAttenuation;
    #endif
}

void GetRampColor(Varyings input, CharacterSurfaceData surfaceData, float NdotL, float rampID, out half4 rampColor, out half3 rampColorWithDiffuse)
{
    float radiance = NdotL * 0.5h + 0.5h;
    // float2 nprLightMapUV = input.uv.xy * _NPRLightMap_ST.xy + _NPRLightMap_ST.zw;
    // half4 nprLightMap = SampleTexture(nprLightMapUV,TEXTURE2D_ARGS(_NPRLightMap, sampler_NPRLightMap));
    GetRampColorWithShadow(TEXTURE2D_ARGS(_RampMap, s_linear_clamp_sampler), rampID, radiance, rampColor);
    // 终末地代码逆向
    half rampMax = max(rampColor.x,rampColor.y);
    rampMax = max(rampMax,rampColor.z);
    half rampMin = min(rampColor.x,rampColor.y);
    rampMin = min(rampMin,rampColor.z);
    float rampRange = rampMax - rampMin;
    rampColor.a = min(rampColor.a, surfaceData.ambientOcclusion);
    rampColor.a = lerp(NdotL, rampColor.a, _DiffuseUseRampA);
    rampColor.rgb = Desaturate(rampColor.rgb, saturate(_RampMapSaturation));
    rampColorWithDiffuse = rampColor.rgb * _SkinLightToneColor;
    rampColor.rgb = rampColor.rgb * rampRange + (1.0h - rampRange);
}

SHADOW_TYPE EvaluateShadow_DirectionalCharacter( LightLoopContext lightLoopContext, PositionInputs posInput,
                                        DirectionalLightData light, BuiltinData builtinData, float NdotLFixed)
{
#ifndef LIGHT_EVALUATION_NO_SHADOWS
    SHADOW_TYPE shadow  = 1.0;
    float shadowMask    = 1.0;
    float NdotL         = NdotLFixed; // Disable contact shadow and shadow mask when facing away from light (i.e transmission)

#ifdef SHADOWS_SHADOWMASK
    // shadowMaskSelector.x is -1 if there is no shadow mask
    // Note that we override shadow value (in case we don't have any dynamic shadow)
    shadow = shadowMask = (light.shadowMaskSelector.x >= 0.0 && NdotL > 0.0) ? dot(BUILTIN_DATA_SHADOW_MASK, light.shadowMaskSelector) : 1.0;
#endif

    if ((light.shadowIndex >= 0) && (light.shadowDimmer > 0))
    {
        shadow = lightLoopContext.shadowValue;

    #ifdef SHADOWS_SHADOWMASK
        int shadowSplitIndex = lightLoopContext.shadowContext.shadowSplitIndex;
        if (shadowSplitIndex < 0)
        {
            shadow = shadowMask;
        }
        else if (shadowSplitIndex == int(_CascadeShadowCount) - 1)
        {
            float fade = lightLoopContext.shadowContext.fade;
            // In the transition code (both dithering and blend) we use shadow = lerp( shadow, 1.0, fade ) for last transition
            // mean if we expend the code we have (shadow * (1 - fade) + fade). Here to make transition with shadow mask
            // we will remove fade and add fade * shadowMask which mean we do a lerp with shadow mask
            shadow = shadow - fade + fade * shadowMask;
        }

        // See comment in EvaluateBSDF_Punctual
        if (light.nonLightMappedOnly)
        {
            shadow = min(shadowMask, shadow);
        }
        else
        {
            // Use shadowmask when shadow value ​​cannot be retrieved due to shadow caster culling.
            float3 camToPixel = posInput.positionWS - GetPrimaryCameraPosition();
            float distanceCamToPixel2 = dot(camToPixel, camToPixel);

            HDDirectionalShadowData dsd = lightLoopContext.shadowContext.directionalShadowData;
            float alpha = saturate(distanceCamToPixel2 * dsd.fadeScale + dsd.fadeBias);
            shadow = min(shadow, lerp(1.0, shadowMask, alpha * alpha));
        }
    #endif

        shadow = lerp(shadowMask.SHADOW_TYPE_REPLICATE, shadow, light.shadowDimmer);
    }

    // Transparents have no contact shadow information
#if !defined(_SURFACE_TYPE_TRANSPARENT) && !defined(LIGHT_EVALUATION_NO_CONTACT_SHADOWS)
{
    // In certain cases (like hair) we allow to force the contact shadow sample.
    #ifdef LIGHT_EVALUATION_CONTACT_SHADOW_DISABLE_NDOTL
        const bool allowContactShadow = true;
    #else
        const bool allowContactShadow = NdotL > 0.0;
    #endif

    shadow = shadow;//min(shadow, allowContactShadow ? GetContactShadow(lightLoopContext, light.contactShadowMask, light.isRayTracedContactShadow) : 1.0);
}
#endif

#ifdef DEBUG_DISPLAY
    if (_DebugShadowMapMode == SHADOWMAPDEBUGMODE_SINGLE_SHADOW && light.shadowIndex == _DebugSingleShadowIndex)
        g_DebugShadowAttenuation = shadow;
#endif

    return shadow;
#else // LIGHT_EVALUATION_NO_SHADOWS
    return 1.0;
#endif
}

DirectLighting CharacterEvaluateBSDF_Directional(LightLoopContext lightLoopContext,
                                        float3 V, float NdotLFixed, half selfShadow, InputData inputData, InputDotData inputDotData, PositionInputs posInput, AdditionalLightData characterLight,
                                        PreLightData preLightData, DirectionalLightData lightData,
                                        BSDFData bsdfData, BuiltinData builtinData, CharacterSurfaceData surfaceData)
{
    DirectLighting result;
    lightData.color = lerp(lightData.color,float3(7, 6.60354, 6.87953),_CharacterLightSceneType);
    float invDimmer = lerp(1,1/lightData.lightDimmer,_CharacterLightSceneType);
    lightData.diffuseDimmer *= invDimmer;
    lightData.specularDimmer *= invDimmer;
    result = CharacterShadeSurface_Directional(lightLoopContext, inputData, inputDotData, posInput, characterLight, builtinData, surfaceData, preLightData, lightData, bsdfData, V, NdotLFixed, selfShadow);
    return result;
}

