// Call SampleEnv function with distance based roughness
float4 SampleEnvWithDistanceBaseRoughnessCharacter(LightLoopContext lightLoopContext,AdditionalLightData additionalLightData, CharacterSurfaceData surfaceData, InputDotData inputDotData, PositionInputs posInput, EnvLightData lightData, float3 R, float perceptualRoughness, float intersectionDistance, float intensity, int sliceIdx = 0)
{
    // Only apply distance based roughness for non-sky reflection probe
    if (lightLoopContext.sampleReflection == SINGLE_PASS_CONTEXT_SAMPLE_REFLECTION_PROBES && IsEnvIndexCubemap(lightData.envIndex))
    {
        perceptualRoughness = lerp(perceptualRoughness, ComputeDistanceBaseRoughness(intersectionDistance, length(R), perceptualRoughness), lightData.distanceBasedRoughness);
    }
    half lod = perceptualRoughness * UNITY_SPECCUBE_LOD_STEPS;  // [Project TA] Dong Wenhai 金属材质优化-自定义mip
    return SampleEnvCharacter(lightLoopContext, additionalLightData, surfaceData, inputDotData, lightData.envIndex, R, lod * lightData.roughReflections, 1, posInput.positionNDC, intensity, _CharacterSkyUseInverseExposure, sliceIdx);
}

