float3 GetDarkColorProtectedReflectCtrl(float3 reflectCtrl, float3 baseColor)
{
    half diffuseLuminance = Luminance(saturate(baseColor));
    half darkProtect = 1.0h - smoothstep(_CharacterSpecInShadowDarkColorProtect, 1.0h, diffuseLuminance);
    float3 ctrl = lerp(reflectCtrl, float3(1.0, 1.0, 1.0), darkProtect);
    ctrl = lerp(ctrl, float3(1.0, 1.0, 1.0), _CharacterSpecInShadowBrightness);
    return _CharacterUseSpecInShadowCtrl > 0.5 ? ctrl : float3(1.0, 1.0, 1.0);
}

