void DirectionalDissolve_ComputeCore(
    float3 positionWS, float percent,
    out float clipValue, out float normalizedPos, out float edgeFactor, out float edgeWidth)
{
    normalizedPos = DirectionalDissolve_CalculatePosition(positionWS);
    edgeWidth = max(_CharDirDissolveEdgeWidth, 0.01);
    float noiseOffset = DirectionalDissolve_GetEdgeNoiseOffset(positionWS, edgeWidth);
    clipValue = percent - normalizedPos + noiseOffset;

    // 边缘因子：距裁剪边界越近越大，使用平方衰减
    float rawEdge = saturate(1.0 - clipValue / edgeWidth);
    edgeFactor = rawEdge * rawEdge; // 等价于 pow(x, 2.0)，避免 pow 开销
}

// outlineWidthProperty / outlineZOffsetProperty：与 Inspector 中 _Outline_Width、_OutlineZOffset 同语义，由调用方传入
float GetModeScaledOutlineWidth(int expandMode, float outlineWidthProperty)
{
    const float OUTLINE_WIDTH_SLIDER_MAX = 1.0;

    const float GF_EFFECTIVE_MAX = 0.5;
    const float CUSTOM_EFFECTIVE_MAX = 4.0;
    const float VS_EFFECTIVE_MAX = 1.0;

    const float OUTLINE_SCALE_GF = GF_EFFECTIVE_MAX / OUTLINE_WIDTH_SLIDER_MAX;
    const float OUTLINE_SCALE_CUSTOM = CUSTOM_EFFECTIVE_MAX / OUTLINE_WIDTH_SLIDER_MAX * 0.4;
    const float OUTLINE_SCALE_VS = VS_EFFECTIVE_MAX / OUTLINE_WIDTH_SLIDER_MAX;
    const float OUTLINE_SCALE_OLD = GF_EFFECTIVE_MAX / OUTLINE_WIDTH_SLIDER_MAX * 0.2;

    float scale = OUTLINE_SCALE_GF;
    if (expandMode == 1) scale = OUTLINE_SCALE_OLD;
    else if (expandMode == 2) scale = OUTLINE_SCALE_CUSTOM;
    else if (expandMode == 3) scale = OUTLINE_SCALE_VS;
    return outlineWidthProperty * scale;
}

