//色阶功能，只包含3个数值的调整，要photoShop中的5个数值的调整，请对结果再使用一次Remap即可
float Levels(float In, float mid, float left, float right)
{
    float normalizedValue = (In - left) / (right - left);
    return pow(normalizedValue , 1.0 / mid);
}

float3 ApplyDye_Hair(float3 baseColor,float alpha, float2 uv)
{
    float3 dyeLevel = ACC(_DyeLevel).xyz;
    float baseLayer = Levels(baseColor.r,dyeLevel.z,dyeLevel.x,dyeLevel.y);

    float4 dyeInfo = SAMPLE_TEXTURE2D(_DyeTex, sampler_DyeTex, uv);

    float layer1_id = dyeInfo.x;
    float layer2_mask = dyeInfo.y;
    float layer3_id = dyeInfo.z;
    float layer3_mask = dyeInfo.w;

    //叠加方式：先计算layer1:底色层。然后再把layer2:发丝层，叠加到底色层，得到结果，然后再把高光层，叠加到这个结果上，得到最终结果，也就是按照123层，一层一层叠，
    float3 finalColor = 0;
    //计算底色层
    float3 layer1Color = Lerp01BetweenABC(layer1_id, ACC(_DyeLayer1_col1).rgb, ACC(_DyeLayer1_col2).rgb, ACC(_DyeLayer1_col3).rgb);
    float3 blendResult_Multi = Blend_Multiply(baseLayer,layer1Color);
    float3 blendResult_Overlay = Blend_Overlay(baseLayer,layer1Color);
    layer1Color = lerp(blendResult_Multi, blendResult_Overlay, ACC(_DyeLayer1_m));
    finalColor = layer1Color;
    //接下来叠加发丝层上去
    float4 layer2Color = float4(ACC(_DyeLayer2_col).rgb,layer2_mask);
    finalColor = Blend_Add( float4(finalColor.rgb,1), layer2Color );
    //最后计算高光层
    float3 layer3Color = Lerp01BetweenABC(layer3_id, ACC(_DyeLayer3_col1).rgb, ACC(_DyeLayer3_col2).rgb, ACC(_DyeLayer3_col3).rgb);
    blendResult_Multi = Blend_Multiply(finalColor,layer3Color);
    blendResult_Overlay = Blend_Overlay(finalColor,layer3Color);
    layer3Color = lerp(blendResult_Multi, blendResult_Overlay, ACC(_DyeLayer3_m));
    //在根据遮罩lerp，与底色混合过度，得到最终结果
    finalColor = lerp(finalColor,layer3Color,layer3_mask);
    //最后叠一层肉色
    float3 layer4Color = ACC(_DyeLayer4_col).rgb;
    blendResult_Multi = Blend_Multiply(finalColor,layer4Color);
    blendResult_Overlay = Blend_Overlay(finalColor,layer4Color);
    layer4Color = lerp(blendResult_Multi, blendResult_Overlay, ACC(_DyeLayer4_m));
    finalColor = lerp(finalColor, layer4Color, alpha);

    return finalColor;
}

float GenerateAngularBinomialValueForSurfaceCell(
    float4 uniformRandom,
    float4 gaussianRandom,
    float2 slopeLerp,
    float footprintOneHitProbability,
    float binomialSmoothWidth,
    float footprintMean,
    float footprintSTD,
    float microfacetCount)
{
    float4 gating;
    if (binomialSmoothWidth > 1e-7)
    {
        gating = saturate(RemapTo01(
            uniformRandom,
            footprintOneHitProbability + binomialSmoothWidth,
            footprintOneHitProbability - binomialSmoothWidth));
    }
    else
    {
        gating = uniformRandom < footprintOneHitProbability;
    }

    float4 gaussian = gaussianRandom * footprintSTD + footprintMean;
    gaussian = clamp(floor(gaussian), 0.0, microfacetCount);
    return BilinearLerp(gating * (1.0 + gaussian), slopeLerp);
}

