// ===================== Physical Parallax (物理/折射) =====================
inline float3 EyeRefractionDirectionWS(float internalIoR, float3 normalWS, float3 viewDirWS)
{
    // 参考 UE4 Human Eye (伪物理折射)
    float airIoR = 1.00029;
    float n = airIoR / max(internalIoR, 1e-3);
    float facing = dot(normalWS, viewDirWS);
    float w = n * facing;
    float k = sqrt(max(0.0, 1 + (w - n) * (w + n)));
    float3 t = (w - k) * normalWS - n * viewDirWS;
    return -SafeNormalize(t);
}

inline float2 EyeParallax_UV_Physical(float2 uv, float3 viewDirWS, float3 normalWS, float3 tangentWS, out half irisMask)
{
    float2 scaleByCenter = max(float2((float)_EyeIrisScaleByCenterX, (float)_EyeIrisScaleByCenterY), 1e-3.xx);
    float2 centerUV = (uv / scaleByCenter + 0.5) - (0.5 / scaleByCenter);

    float IrisUVRadius = (float)_EyeIrisUVRadius;
    float LimbusUVWidth = max((float)_EyeLimbusUVWidth, 1e-5);
    float2 cuv = centerUV - float2(0.5f, 0.5f);
    float r = (length(cuv) - (IrisUVRadius - LimbusUVWidth)) / LimbusUVWidth;
    float m = saturate(1 - r);
    m = smoothstep(0, 1, m);

    float3 t = EyeRefractionDirectionWS(_EyeInternalIoR, normalWS, viewDirWS);

    float eyeDepth = (_EyeUseDepthMapAsThickness > 0.5h)
                         ? SampleTexture(centerUV, TEXTURE2D_ARGS(_EyeDepthMap, sampler_BaseMap)).r
                         : m;

    float irisDepth = max(eyeDepth - (float)_EyeThicknessBias, 0) * (float)_EyeThicknessScale;
    float cosAlpha = dot(viewDirWS, normalWS);
    float heightW = irisDepth / lerp((float)_EyeThicknessMinDenom, 1, cosAlpha * cosAlpha);
    float3 scaledDir = heightW * t;

    float3 eyeTangentWS = SafeNormalize(tangentWS - dot(tangentWS, normalWS) * normalWS);
    float3 eyeBinormWS = SafeNormalize(cross(eyeTangentWS, normalWS));
    float2 offsetTS = float2(dot(eyeTangentWS, scaledDir), dot(eyeBinormWS, scaledDir));

    float2 scaleOffset = float2(-1, 1) * IrisUVRadius * offsetTS;
    float2 refractedUV = centerUV + scaleOffset;
    refractedUV = lerp(centerUV, refractedUV, m);
    float2 ajuastUV = (refractedUV - 0.5) * (1 / (2 * IrisUVRadius)) + 0.5;

    float2 UVcentered = ajuastUV - float2(0.5f, 0.5f);
    float UVlength = length(UVcentered);
    float2 UVmax = normalize(UVcentered) * 0.5f;
    float2 UVscaled = lerp(UVmax, float2(0.f, 0.f), saturate((1.f - UVlength * 2.f) * (float)_EyePupilScale));
    float2 fianlUV = UVscaled + float2(0.5f, 0.5f);

    irisMask = (half)m;
    return fianlUV;
}

void ApplyEyeVertexParallax(float2 uv0, inout float3 positionOS, float3 normalOS)
{
    float2 baseUV = uv0 * _BaseMap_ST.xy + _BaseMap_ST.zw;
    half texMask = SAMPLE_TEXTURE2D_LOD(_EyeParallaxMaskTex, sampler_EyeParallaxMaskTex, baseUV, 0).r;

    float3 camPosOS  = TransformWorldToObject(GetCameraPositionWS());
    float3 viewDirOS = camPosOS - positionOS;
    half   viewMask  = EyeVertexParallax_ViewNormalMask(viewDirOS, normalOS);

    half   finalMask = texMask * viewMask;
    float3 nOS       = SafeNormalize(normalOS);

    positionOS -= nOS * (float)_EyeVertexParallaxOffsetZ * (float)finalMask;
}

// 计算脸部轴向数据（根据 _CustomMatrixFlag 选择脚本传入值或默认值）
inline void ComputeFaceAxisData(out float3 faceForwardWS, out float3 faceRightWS, out float3 headBonePosWS)
{
    float customMatrixFlag = _CustomMatrixFlag;
    float3 faceForwardOS =  _FaceForward.xyz;
    float3 faceRightOS = _FaceRight.xyz;
    float4 matrixRow0 = _HeadBoneMatrix0;
    float4 matrixRow1 = _HeadBoneMatrix1;
    float4 matrixRow2 = _HeadBoneMatrix2;
    float4 matrixRow3 = _HeadBoneMatrix3;

    CharFaceDirGpuData gpuData;
    if (TryGetCharFaceDirGpuData(gpuData))
    {
        customMatrixFlag = gpuData.Parameters.x;
        faceForwardOS = gpuData.FaceForward.xyz;
        faceRightOS = gpuData.FaceRight.xyz;
        matrixRow0 = gpuData.HeadBoneMatrix0;
        matrixRow1 = gpuData.HeadBoneMatrix1;
        matrixRow2 = gpuData.HeadBoneMatrix2;
        matrixRow3 = gpuData.HeadBoneMatrix3;
    }

    float matrixFlag = step(0.5, customMatrixFlag);
    float4x4 scriptMatrix = float4x4(matrixRow0, matrixRow1, matrixRow2, matrixRow3);
    float4x4 rawObjectToWorld = GetRawUnityObjectToWorld();
    // float4x4 rawObjectToWorld = UNITY_MATRIX_M;
    float4x4 headBoneMatrix;
    headBoneMatrix[0] = lerp(rawObjectToWorld[0], scriptMatrix[0], matrixFlag);
    headBoneMatrix[1] = lerp(rawObjectToWorld[1], scriptMatrix[1], matrixFlag);
    headBoneMatrix[2] = lerp(rawObjectToWorld[2], scriptMatrix[2], matrixFlag);
    headBoneMatrix[3] = lerp(rawObjectToWorld[3], scriptMatrix[3], matrixFlag);
    faceForwardWS = mul((float3x3)headBoneMatrix, faceForwardOS);
    faceRightWS = mul((float3x3)headBoneMatrix, faceRightOS);
    headBonePosWS = headBoneMatrix._m03_m13_m23;
}

// 计算脸部 SDF 相关数据（光照方向与脸部轴向的关系）
inline half2 ComputeFaceSDF(Light_Character mainLight, AdditionalLightData addLightData, float3 faceForwardWS, float3 faceRightWS)
{
    float2 lightDir_XZ = normalize(addLightData.diffuseDir.xz);

    float3 frontDir = faceForwardWS;
    float3 rightDir = faceRightWS;

#if defined(_VERTEX_SKINNING_ON)
    // GPU Skinning 模式下，使用 Root Bone 信息覆盖轴向
    GpuSkinningGetRootBoneInfo(_VertexSkinning_RootBoneIndex, _VertexSkinning_RootBoneForward.xyz, _VertexSkinning_RootBoneRight.xyz, frontDir, rightDir);
#endif

    float2 frontDir_XZ = normalize(frontDir.xz);
    float2 rightDir_XZ = normalize(rightDir.xz);

    half reversal = -1.0f;

    float RdotL = dot(rightDir_XZ, lightDir_XZ) * reversal; //模型水平右向方向与灯光的夹角值，1为灯光在模型右边，-1为灯光在模型左边
    float FdotL = dot(frontDir_XZ, lightDir_XZ);

    float lightSign = 2.0f * step(RdotL, 0.0f) - 1.0f; // 计算灯光在左边还是右边,大于0是右手灯光，小于0是左右灯光

    // 返回 SDF 计算所需的数据
    return half2(FdotL, lightSign);
}

PreLightData GetPreLightDataCharacterSkin(float3 V, PositionInputs posInput, inout BSDFData bsdfData)
{
    PreLightData preLightData;
    ZERO_INITIALIZE(PreLightData, preLightData);

    float3 N = bsdfData.normalWS;
    preLightData.NdotV = dot(N, V);
    preLightData.iblPerceptualRoughness = bsdfData.perceptualRoughness;

    float clampedNdotV = ClampNdotV(preLightData.NdotV);

    // We modify the bsdfData.fresnel0 here for iridescence
    if (HasFlag(bsdfData.materialFeatures, MATERIALFEATUREFLAGS_LIT_IRIDESCENCE))
    {
        float viewAngle = clampedNdotV;
        float topIor = 1.0; // Default is air
        if (HasFlag(bsdfData.materialFeatures, MATERIALFEATUREFLAGS_LIT_CLEAR_COAT))
        {
            topIor = lerp(1.0, CLEAR_COAT_IOR, bsdfData.coatMask);
            // HACK: Use the reflected direction to specify the Fresnel coefficient for pre-convolved envmaps
            if (bsdfData.coatMask != 0.0f) // We must make sure that effect is neutral when coatMask == 0
                viewAngle = sqrt(1.0 + Sq(1 / topIor) * (Sq(dot(bsdfData.normalWS, V)) - 1.0));
        }

        if (bsdfData.iridescenceMask > 0.0)
        {
            bsdfData.fresnel0 = lerp(bsdfData.fresnel0, EvalIridescence(topIor, viewAngle, bsdfData.iridescenceThickness, bsdfData.fresnel0), bsdfData.iridescenceMask);
        }
    }

    // We modify the bsdfData.fresnel0 here for clearCoat
    if (HasFlag(bsdfData.materialFeatures, MATERIALFEATUREFLAGS_LIT_CLEAR_COAT))
    {
        // Fresnel0 is deduced from interface between air and material (Assume to be 1.5 in Unity, or a metal).
        // but here we go from clear coat (1.5) to material, we need to update fresnel0
        // Note: Schlick is a poor approximation of Fresnel when ieta is 1 (1.5 / 1.5), schlick target 1.4 to 2.2 IOR.
        bsdfData.fresnel0 = lerp(bsdfData.fresnel0, ConvertF0ForAirInterfaceToF0ForClearCoat15(bsdfData.fresnel0), bsdfData.coatMask);

        preLightData.coatPartLambdaV = GetSmithJointGGXPartLambdaV(clampedNdotV, CLEAR_COAT_ROUGHNESS);
        preLightData.coatIblR = reflect(-V, N);
        preLightData.coatIblF = F_Schlick(CLEAR_COAT_F0, clampedNdotV) * bsdfData.coatMask;
        preLightData.coatReflectionWeight = 0.0;
    }

    // Handle IBL + area light + multiscattering.
    // Note: use the not modified by anisotropy iblPerceptualRoughness here.
    float specularReflectivity;
    GetPreIntegratedFGDGGXAndDisneyDiffuse(clampedNdotV, preLightData.iblPerceptualRoughness, bsdfData.fresnel0, preLightData.specularFGD, preLightData.diffuseFGD, specularReflectivity);
// #ifdef USE_DIFFUSE_LAMBERT_BRDF
    preLightData.diffuseFGD = 1.0;
// #endif

#ifdef LIT_USE_GGX_ENERGY_COMPENSATION
    // Ref: Practical multiple scattering compensation for microfacet models.
    // We only apply the formulation for metals.
    // For dielectrics, the change of reflectance is negligible.
    // We deem the intensity difference of a couple of percent for high values of roughness
    // to not be worth the cost of another precomputed table.
    // Note: this formulation bakes the BSDF non-symmetric!
    preLightData.energyCompensation = 1.0 / specularReflectivity - 1.0;
#else
    preLightData.energyCompensation = 0.0;
#endif // LIT_USE_GGX_ENERGY_COMPENSATION

    float3 iblN;

    // We avoid divergent evaluation of the GGX, as that nearly doubles the cost.
    // If the tile has anisotropy, all the pixels within the tile are evaluated as anisotropic.
    if (HasFlag(bsdfData.materialFeatures, MATERIALFEATUREFLAGS_LIT_ANISOTROPY))
    {
        float TdotV = dot(bsdfData.tangentWS,   V);
        float BdotV = dot(bsdfData.bitangentWS, V);

        preLightData.partLambdaV = GetSmithJointGGXAnisoPartLambdaV(TdotV, BdotV, clampedNdotV, bsdfData.roughnessT, bsdfData.roughnessB);

        // perceptualRoughness is use as input and output here
        GetGGXAnisotropicModifiedNormalAndRoughness(bsdfData.bitangentWS, bsdfData.tangentWS, N, V, bsdfData.anisotropy, preLightData.iblPerceptualRoughness, iblN, preLightData.iblPerceptualRoughness);
    }
    else
    {
        preLightData.partLambdaV = GetSmithJointGGXPartLambdaV(clampedNdotV, bsdfData.roughnessT);
        iblN = N;
    }

    preLightData.iblR = reflect(-V, iblN);

    // Area light
    // UVs for sampling the LUTs
    // We use V = sqrt( 1 - cos(theta) ) for parametrization which is kind of linear and only requires a single sqrt() instead of an expensive acos()
    float cosThetaParam = sqrt(1 - clampedNdotV); // For Area light - UVs for sampling the LUTs
    float2 uv = Remap01ToHalfTexelCoord(float2(bsdfData.perceptualRoughness, cosThetaParam), LTC_LUT_SIZE);

    // Note we load the matrix transpose (avoid to have to transpose it in shader)
#ifdef USE_DIFFUSE_LAMBERT_BRDF
    preLightData.ltcTransformDiffuse = k_identity3x3;
#else
    // Get the inverse LTC matrix for Disney Diffuse
    preLightData.ltcTransformDiffuse      = 0.0;
    preLightData.ltcTransformDiffuse._m22 = 1.0;
    preLightData.ltcTransformDiffuse._m00_m02_m11_m20 = SAMPLE_TEXTURE2D_ARRAY_LOD(_LtcData, s_linear_clamp_sampler, uv, LTCLIGHTINGMODEL_DISNEY_DIFFUSE, 0);
#endif

    // Get the inverse LTC matrix for GGX
    // Note we load the matrix transpose (avoid to have to transpose it in shader)
    preLightData.ltcTransformSpecular      = 0.0;
    preLightData.ltcTransformSpecular._m22 = 1.0;
    preLightData.ltcTransformSpecular._m00_m02_m11_m20 = SAMPLE_TEXTURE2D_ARRAY_LOD(_LtcData, s_linear_clamp_sampler, uv, LTCLIGHTINGMODEL_GGX, 0);

    // Construct a right-handed view-dependent orthogonal basis around the normal
    preLightData.orthoBasisViewNormal = GetOrthoBasisViewNormal(V, N, preLightData.NdotV);
    // ……（节选到此，完整函数仅本地预览）

float sdRoundedBox(float2 p, float2 b, float r)
{
    r = min(r, min(b.x, b.y));
    return sdBox(p, b - r) - r;
}

// 视口几何剔除接口
void ViewportShapeDitherCutoff(float2 screenUV, float3 positionWS)
{
    float transparency = _ViewportShapeCutoffTransparency;

    //Shape Mask(目前只有圆形剔除)
    float shapeMask;
    float2 sphereUVDiff = (screenUV - _ViewportShapeCutoffSphereCenter) * (_ScreenParams.xx / _ScreenParams.yx);
    float sphereMask = saturate(length(sphereUVDiff) / _ViewportShapeCutoffSphereRadius);
    sphereMask = 1 - smoothstep(0.999 - _ViewportShapeCutoffSphereEdgeSmoothness, 0.999, sphereMask);
    shapeMask = _ViewportShapeCutoffType == VIEWPORT_SHAPE_CUTOFF_TYPE_SPHERE ? sphereMask : 1;

    //DepthMask
    float eyeDepth = LinearEyeDepth(positionWS, GetWorldToViewMatrix());
    float depthMask = smoothstep(_ViewportShapeCutoffMaxDistance, _ViewportShapeCutoffMaxDistance - _ViewportShapeCutoffDistanceSmoothness, eyeDepth);

    float mask = shapeMask * depthMask;
    transparency = lerp(1, transparency, mask);
    float clipValue = 0.99 - step(transparency, GetDitherThreshold(screenUV * _ScreenParams.xy * rcp(HOLE_SIZE)));

    clip(clipValue);
}
